import { readFile, rename, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

const file = join(process.cwd(), 'data', 'books.json');
let pending = Promise.resolve();

export async function getBooks() {
  try {
    const contents = await readFile(file, 'utf8');
    const books = JSON.parse(contents);
    if (!Array.isArray(books)) throw new Error('Invalid books file: expected an array');
    return books;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

export async function getBook(id) {
  return (await getBooks()).find((book) => book.id === id);
}

// Serialize writes within this server process and rename a complete file into place.
function updateBooks(change) {
  const result = pending.then(async () => {
    const books = await getBooks();
    const value = change(books);
    const temporaryFile = `${file}.${randomUUID()}.tmp`;
    try {
      await writeFile(temporaryFile, JSON.stringify(books, null, 2) + '\n', 'utf8');
      await rename(temporaryFile, file);
    } catch (error) {
      const { unlink } = await import('node:fs/promises');
      await unlink(temporaryFile).catch(() => {});
      throw error;
    }
    return value;
  });
  pending = result.catch(() => {});
  return result;
}

export function addBook({ title, author, notes }) {
  return updateBooks((books) => {
    const book = {
      id: randomUUID(),
      title,
      author,
      notes,
      status: 'reading',
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    books.unshift(book);
    return book;
  });
}

