{"path":"app/actions.js","content":"'use server';

import { revalidatePath } from 'next/cache';
import { redirect } from 'next/navigation';
import { addBook, finishBook } from '../lib/books.js';

export async function createBook(formData) {
  const title = String(formData.get('title') ?? '').trim();
  const author = String(formData.get('author') ?? '').trim();
  const notes = String(formData.get('notes') ?? '').trim();

  if (!title || !author || title.length > 200 || author.length > 200 || notes.length > 10000) {
    redirect('/?error=invalid');
  }

  const book = await addBook({ title, author, notes });
  revalidatePath('/');
  redirect(`/books/${book.id}`);
}

export async function markFinished(formData) {
  const id = String(formData.get('id') ?? '');
  const book = await finishBook(id);
  if (!book) redirect('/');
  revalidatePath('/');
  revalidatePath(`/books/${id}`);
  redirect(formData.get('from') === 'detail' ? `/books/${id}` : '/');
}
"}

